===== res://validation_games/orbit_collector/scripts/orb.gd =====
extends Area3D
## 能量球收集物：玩家（group "player"）进入时发出 collected 信号并消失。

signal collected(orb: Area3D)

var is_collected: bool = false

func _ready() -> void:
	body_entered.connect(_on_body_entered)

func _on_body_entered(body: Node3D) -> void:
	if is_collected:
		return
	if body.is_in_group("player"):
		_collect()

func _collect() -> void:
	is_collected = true
	collected.emit(self)
	visible = false
	set_deferred("monitoring", false)
	# 禁用碰撞形状
	for child in get_children():
		if child is CollisionShape3D:
			child.set_deferred("disabled", true)

===== res://validation_games/orbit_collector/scripts/player.gd =====
extends CharacterBody3D
## Orbit Collector 玩家：键盘四向移动、收集能量球、解锁并进入出口获胜。

signal orbs_changed(collected: int, total: int)
signal exit_status_changed(unlocked: bool)
signal victory

@export var move_speed: float = 7.0
@export var total_orbs: int = 3

var orbs_collected: int = 0
var exit_unlocked: bool = false
var won: bool = false

@onready var gate: MeshInstance3D = get_node("../Props/Exit/Gate")
@onready var gate_locked_mat: Material = load("res://validation_games/orbit_collector/materials/gate_locked_mat.tres")
@onready var gate_unlocked_mat: Material = load("res://validation_games/orbit_collector/materials/gate_unlocked_mat.tres")
@onready var exit_area: Area3D = get_node("../Props/Exit/ExitArea")

func _ready() -> void:
	add_to_group("player")
	# 监听所有能量球
	for orb in get_tree().get_nodes_in_group("orbs"):
		(orb as Area3D).collected.connect(_on_orb_collected)
	# 监听出口
	exit_area.body_entered.connect(_on_exit_body_entered)
	orbs_changed.emit(orbs_collected, total_orbs)

func _physics_process(_delta: float) -> void:
	if won:
		velocity = Vector3.ZERO
		return
	var input_dir := Vector2.ZERO
	if Input.is_action_pressed("move_left"):
		input_dir.x -= 1.0
	if Input.is_action_pressed("move_right"):
		input_dir.x += 1.0
	if Input.is_action_pressed("move_forward"):
		input_dir.y -= 1.0
	if Input.is_action_pressed("move_back"):
		input_dir.y += 1.0
	input_dir = input_dir.normalized()
	velocity = Vector3(input_dir.x, 0.0, input_dir.y) * move_speed
	move_and_slide()

func _on_orb_collected(orb: Area3D) -> void:
	if won:
		return
	orbs_collected += 1
	orbs_changed.emit(orbs_collected, total_orbs)
	if orbs_collected >= total_orbs:
		_unlock_exit()

func _unlock_exit() -> void:
	exit_unlocked = true
	gate.material_override = gate_unlocked_mat
	exit_status_changed.emit(true)

func _on_exit_body_entered(body: Node3D) -> void:
	if won or not exit_unlocked:
		return
	if body == self:
		won = true
		victory.emit()

===== res://validation_games/orbit_collector/scripts/hud.gd =====
extends CanvasLayer
## HUD：显示收集进度与状态提示，监听 Player 信号。

@onready var counter_label: Label = $Counter
@onready var status_label: Label = $Status

var _player: CharacterBody3D

func _ready() -> void:
	_player = get_tree().get_first_node_in_group("player") as CharacterBody3D
	if _player == null:
		return
	_player.orbs_changed.connect(_on_orbs_changed)
	_player.exit_status_changed.connect(_on_exit_status_changed)
	_player.victory.connect(_on_victory)

func _on_orbs_changed(collected: int, total: int) -> void:
	counter_label.text = "能量球: %d / %d" % [collected, total]

func _on_exit_status_changed(unlocked: bool) -> void:
	if unlocked:
		status_label.text = "出口已解锁！前往绿色出口！"
		status_label.modulate = Color(0.13, 0.77, 0.34)

func _on_victory() -> void:
	status_label.text = "🎉 获胜！你收集了全部能量球！"
	status_label.modulate = Color(1.0, 0.84, 0.0)
	counter_label.text = "能量球: %d / %d" % [3, 3]

===== res://validation_games/orbit_collector/scripts/camera.gd =====
extends Camera3D
## 俯视跟随相机：平滑跟随玩家，保持固定高度与偏移。

@export var follow_offset := Vector3(0.0, 10.0, 4.0)
@export var smooth_speed: float = 5.0

@onready var _player: Node3D = get_node("../Player")

func _physics_process(delta: float) -> void:
	if _player == null:
		return
	var target := _player.global_position + follow_offset
	global_position = global_position.lerp(target, 1.0 - exp(-smooth_speed * delta))

